    "Kebenaran terperinci mengasingkan pengendali, kakitangan pematuhan, penyemak keselamatan, juruteknik dan pemandu.",
  pub_trust_3_t: "Komunikasi peranti selamat",
  pub_trust_3_d:
    "Gerbang Orange Pi yang diperuntukkan menerbitkan melalui saluran WSS/AMQPS disulitkan dengan kelayakan broker per-peranti.",
  pub_trust_4_t: "Privasi data pemandu",
  pub_trust_4_d:
    "Pemandu hanya melihat syif, skor dan rayuan mereka sendiri; rentetan DTC mentah ditanggalkan sebelum penyimpanan telemetri.",
  pub_trust_5_t: "Semakan peristiwa pemanduan telus",
  pub_trust_5_d:
    "Penilaian insiden mengekalkan konteks syif dan membolehkan pemandu memfailkan rayuan untuk semakan manusia terdokumentasi.",
  pub_trust_6_t: "Pengekalan data sejarah yang sesuai",
  pub_trust_6_d:
    "Pengekalan sejarah menguatkuasakan tetingkap yang ditakrifkan pelan dengan kemas merentasi 30, 90, 180, atau 365 hari.",

  pub_faq_eyebrow: "SOALAN LAZIM",
  pub_faq_heading: "Jawapan untuk pengendali armada dan ketua teknikal.",
  pub_faq_q1: "Apakah itu CarLink?",
  pub_faq_a1:
    "CarLink ialah platform SaaS pengurusan armada berkeupayaan IoT untuk pengendali teksi, organisasi e-panggilan dan armada komersial. Ia menyatukan telemetri kenderaan, penunjuk kesihatan OBD2, sesi pemandu NFC, tarikh akhir pematuhan dan kepintaran liputan 4G/LTE ke dalam satu ruang kerja awan mengikut peranan.",
  pub_faq_q2: "Bagaimanakah CarLink memantau kenderaan?",
  pub_faq_a2:
    "Setiap kenderaan yang ditauliahkan menjalankan gerbang IoT Orange Pi yang diperuntukkan untuk mengumpul lokasi GNSS, kelajuan, peristiwa IMU, kualiti isyarat selular LTE dan parameter OBD2, kemudian menstrim pemerhatian melalui TLS ke saluran penyerapan awan CarLink.",
  pub_faq_q3: "Adakah CarLink memerlukan peranti IoT?",
  pub_faq_a3:
    "Ya untuk telemetri kenderaan langsung, diagnostik OBD2, pengesahan syif NFC dan pemetaan liputan selular. Organisasi masih boleh mengkonfigurasi kenderaan, pemandu dan jadual pematuhan terlebih dahulu, manakala gerbang terurus memerlukan pentauliahan dan pengaktifan juruteknik.",
  pub_faq_q4: "Bolehkah berbilang kakitangan menguruskan armada yang sama?",
  pub_faq_a4:
    "Ya. CarLink ialah berbilang penyewa mengikut organisasi dan menguatkuasakan kebenaran berasaskan peranan di pelayan, membolehkan pengurus operasi, penyemak keselamatan, kakitangan pematuhan dan pemerhati bekerja dalam organisasi yang sama tanpa mendedahkan data penyewa lain.",
  pub_faq_q5: "Bagaimanakah pemandu dikenal pasti?",
  pub_faq_a5:
    "Pemandu menyentuh kad NFC yang ditetapkan pada pembaca terhubung kenderaan. CarLink mengesahkan kelayakan kad disahkan HMAC untuk membuka dan menutup syif pemandu, mengaitkan perjalanan dan peristiwa pemanduan kepada sesi pemandu aktif.",
  pub_faq_q6: "Apakah yang berlaku apabila sambungan selular terputus?",
  pub_faq_a6:
    "Paket yang hilang dianggap secara jujur sebagai pemerhatian tiada dan bukannya data rekaan. Papan pemuka membezakan paket lama daripada kemas kini terkini dan merekodkan telemetri liputan (pengendali, RSRP, SINR) di mana sahaja pemerhatian tiba supaya koridor lemah dapat dikenal pasti.",
  pub_faq_q7: "Bolehkah CarLink memantau diagnostik kenderaan?",
  pub_faq_a7:
    "CarLink menjejaki penunjuk OBD2 langsung seperti kelajuan kenderaan, RPM enjin, anggaran berkaitan bahan api, status lampu MIL dan kehadiran kerosakan. Untuk privasi, senarai kod DTC mentah ditanggalkan sebelum penyimpanan; pengendali boleh meminta imbasan lanjutan pegun dan penjelasan kod Google AI sementara pilihan apabila diperlukan.",
  pub_faq_q8: "Bagaimanakah akses berasaskan langganan berfungsi?",
  pub_faq_a8:
    "Organisasi memilih pelan mengikut saiz bilangan kenderaan, bilangan pemandu, tetingkap pengekalan sejarah (contohnya 30, 90, 180, atau 365 hari), serta modul keselamatan dan liputan selular pilihan. Akses operasi berbayar diaktifkan sebaik sahaja invois langganan organisasi disahkan.",

