  pub_cta_heading:
    "Armada yang lebih pintar bermula dengan gambaran lebih jelas.",
  pub_cta_desc:
    "Satukan data kenderaan, wawasan pemandu dan keutamaan operasi anda ke dalam satu platform terhubung.",
