  pub_faq_eyebrow: "常见问题",
  pub_faq_heading: "面向车队运营方与技术负责人的解答。",
  pub_faq_q1: "什么是 CarLink？",
  pub_faq_a1:
    "CarLink 是面向出租车运营方、网约车组织及商用车队的物联网车队管理 SaaS 平台。它将车辆遥测、OBD2 健康指标、NFC 驾驶员会话、合规期限与 4G/LTE 网络覆盖洞察整合到一个按角色隔离的云端工作区中。",
  pub_faq_q2: "CarLink 如何监控车辆？",
  pub_faq_a2:
    "每辆完成调试的车辆均搭载 Orange Pi 物联网网关，采集 GNSS 定位、车速、IMU 事件、LTE 信号质量与 OBD2 参数，并通过 TLS 传输至 CarLink 云端摄取管道。",
  pub_faq_q3: "CarLink 是否需要物联网硬件设备？",
  pub_faq_a3:
    "实时车辆遥测、OBD2 诊断、NFC 班次认证与蜂窝覆盖测绘需要配合硬件使用。不过组织可以先配置车辆、驾驶员和合规日程，受管网关需由技术人员完成调试与激活。",
  pub_faq_q4: "多名员工可以共同管理同一支车队吗？",
  pub_faq_a4:
    "可以。CarLink 按组织实现多租户隔离并在服务端强制执行基于角色的权限控制，允许运营经理、安全审核员、合规人员与观察员在同一组织内协作，同时绝不泄露其他租户数据。",
  pub_faq_q5: "系统如何识别驾驶员？",
  pub_faq_a5:
    "驾驶员将分配的 NFC 卡轻触车载读卡器即可。CarLink 会验证经 HMAC 签名的卡片凭据，从而开启或结束班次，并将行程与驾驶事件准确归属至当前活跃的驾驶员会话。",
  pub_faq_q6: "蜂窝网络断连时会发生什么？",
  pub_faq_a6:
    "缺失的数据包会被如实记录为无观测数据，绝不伪造填充。仪表盘会区分过时数据包与近期更新，并在有信号的位置持续记录运营商、RSRP 与 SINR 覆盖数据，以便识别信号薄弱路段。",
  pub_faq_q7: "CarLink 支持车辆诊断监控吗？",
  pub_faq_a7:
    "CarLink 可追踪车速、发动机转速、燃油相关估算、MIL 故障指示灯状态及故障存在标志等实时 OBD2 指标。出于隐私保护，原始 DTC 代码列表在入库前会被剥离；运营人员可按需发起静止扩展扫描及可选的即时 Google AI 故障解释。",
  pub_faq_q8: "基于订阅的访问机制如何运作？",
  pub_faq_a8:
    "组织可根据车辆数量、驾驶员数量、历史保留窗口（例如 30、90、180 或 365 天）以及可选的安全与蜂窝覆盖模块选择套餐。组织的订阅发票确认付款后，付费运营权限即刻生效。",

