  billing_vehicles_used_limit: "பயன்படுத்தப்பட்ட வாகனங்கள் / வரம்பு",
  billing_drivers_used_limit: "பயன்படுத்தப்பட்ட ஓட்டுநர்கள் / வரம்பு",
  billing_driver_retention: "ஓட்டுநர் வரலாறு சேமிப்பு",
