  billing_safety_feature: "ஓட்டுநர் பாதுகாப்பு அம்சம்",
  billing_renewal_notice:
    "புதுப்பித்தல் கட்டணக் காலத்தை நீட்டிக்கும்; ஆனால் SaaS இடைநிறுத்தம் அல்லது செயலிழப்பை மீற முடியாது. செயல்பாட்டு அணுகலும் கட்டண அனுமதியும் தனித்தனியானவை.",
