  billing_col_retention_days: "சேமிப்பு (நாட்கள்)",
  billing_col_min_telemetry: "குறைந்தபட்ச டெலிமெட்ரி (s)",
  billing_invoices_title: "விலைப்பட்டியல்கள்",
  billing_col_amount: "தொகை",
  billing_inspect_invoice: "விலைப்பட்டியலைப் பார்",
  billing_issue_workflow_title: "சந்தா விலைப்பட்டியல் வெளியிடு",
  billing_issue_workflow_desc:
    "சேவையகம் விலையை நிர்ணயித்து திட்டத்தைப் பதிவு செய்யும். விலைப்பட்டியல் வெளியீடு கட்டணமல்ல; அணுகலை வழங்காது.",
  billing_invoice_details: "விலைப்பட்டியல் விவரங்கள்",
  billing_purchased_snapshot: "வாங்கப்பட்ட திட்டப் பதிவு",
  billing_request_checkout: "கட்டணத்தைக் கோரு",
  billing_request_checkout_desc:
    "{amount} தொகைக்குக் கட்டணம் கோரவா? இது உண்மையான கட்டண முயற்சியை உருவாக்கக்கூடும். இயக்குநர் சமரசமின்றி நிச்சயமற்ற கட்டணங்களை மீண்டும் முயற்சிக்க வேண்டாம்.",
  billing_void_invoice: "கட்டணத்திற்கு முந்தைய விலைப்பட்டியலை ரத்து செய்",
  billing_reconcile_permission_alert:
    "அங்கீகரிக்கப்பட்ட கட்டண மேலாளர் இக்கட்டணத்தைச் சமரசம் செய்ய வேண்டும். விலைப்பட்டியல் அணுகல் கட்டண-நிலை அனுமதியை வழங்காது.",
  billing_payment_attempt_alert:
    "இந்த விலைப்பட்டியலில் கட்டண முயற்சி உள்ளது. ரத்து/மாற்றம் கிடைக்காது; இயக்குநருடன் சமரசம் செய்யவும்.",

  comp_subtitle:
    "சேவையகம் கணக்கிட்ட காப்பீடு, சான்று மதிப்பாய்வு மற்றும் நிறுவன உள்ளூர் நாட்காட்டி தேதிகள்.",
  comp_upload_not_verified_alert:
    "பதிவேற்றப்பட்ட ஆவணம் சரிபார்க்கப்பட்ட காப்பீடல்ல. சேவையகத்தால் சரிபார்க்கப்பட்ட புதுப்பிப்புகள் மட்டுமே இணக்க நிலையில் பங்கேற்கும்.",
  comp_tab_status: "தற்போதைய நிலை",
  comp_status_scope:
    "அதிகபட்சம் 100 கடமைகள். கீழே உள்ள வாகன வடிகட்டி ஏற்றப்பட்ட வரிசைகளுக்கு மட்டுமே பொருந்தும்.",
  comp_btn_obligation_renewal: "கடமை / புதுப்பிப்பு",
  comp_btn_evidence_history: "சான்று & வரலாறு",
  comp_tab_pending: "சரிபார்ப்பு நிலுவையில்",
  comp_btn_evidence_verify: "சான்று & சரிபார்",
  comp_tab_obligations: "கடமைகள்",
  comp_btn_create_obligation: "கடமையை உருவாக்கு",
