  pub_plans_heading: "உங்கள் வாகனக் குழுவுடன் வளர வடிவமைக்கப்பட்டது.",
  pub_plans_intro:
    "வாகன எண்ணிக்கை, ஓட்டுநர் எண்ணிக்கை, தரவு சேமிப்புக் காலம் (30, 90, 180, அல்லது 365 நாட்கள்), ஓட்டுநர் பாதுகாப்பு மதிப்பெண்கள், செல்லுலார் அலைவரிசைப் பகுப்பாய்வு மற்றும் செயல்பாட்டு அறிக்கைகளுக்குப் பொருத்தமான திட்டங்களை நிறுவனங்கள் தேர்ந்தெடுக்கின்றன.",
