  pub_scrolly_eyebrow: "தரவு தடையின்றி எவ்வாறு பாய்கிறது",
  pub_scrolly_heading:
    "இயந்திரத் துறையிலிருந்து நுண்ணறிவு வரை ஒரு வாகனப் பாக்கெட்டைப் பின்தொடரவும்.",
  pub_scrolly_lead:
    "CarLink இன் ஒவ்வொரு அடுக்கையும் காணக் கீழே உருட்டவும் — ஒரே இணைக்கப்பட்ட வாகனம் OBD2, NFC, LTE மற்றும் இணக்கச் சிக்னல்களை எவ்வாறு மாற்றுகிறது என்பதைப் பாருங்கள்.",
  pub_scrolly_stage_title: "CarLink நேரடி கட்டமைப்பு · மாதிரி",
  pub_scrolly_tabs_aria: "அத்தியாயத் தாவல்கள்",
  pub_ch1_pill: "01 டெலிமெட்ரி",
  pub_ch1_eyebrow: "அத்தியாயம் 01 · முனை பிடிப்பு",
  pub_ch1_title: "மூலத்திலேயே பிடிக்கப்படும் நேரடி வாகன நிலை.",
  pub_ch1_desc:
    "நிறுவப்பட்ட Orange Pi நுழைவாயில்கள் OBD2 வாகன வேகம், இயந்திர RPM, MIL கோளாறு கொடிகள் மற்றும் GNSS ஆயங்களைத் தொடர்ந்து படித்து, உண்மையான சென்சார் பாக்கெட்டுகளைப் பழைய கடிகாரங்களிலிருந்து பிரிக்கின்றன.",
  pub_ch1_h1: "மூல DTC குறியீடுகளைக் கசியவிடாமல் OBD2 PID வேகம், RPM & கோளாறு நிலை",
  pub_ch1_h2: "நேர்மையான பாக்கெட் புதுமை & நுழைவாயில் இணைப்புப் பிரிப்பு",
  pub_ch1_h3: "குழுத் திட்ட இடைவெளிகளுக்கு ஏற்ப தொடர்ச்சியான 5-வினாடி சுழற்சி",
  pub_ch2_pill: "02 NFC & பாதுகாப்பு",
  pub_ch2_eyebrow: "அத்தியாயம் 02 · ஓட்டுநர் இணைப்பு",
  pub_ch2_title: "ஒவ்வொரு பயணமும் நிகழ்வும் அங்கீகரிக்கப்பட்ட ஓட்டுநருடன் இணைக்கப்படுகிறது.",
  pub_ch2_desc:
    "ஓட்டுநர்கள் நுழைவாயில் படிப்பானில் தம் NFC அட்டையைத் தட்டிப் பணி மாற்றங்களைத் தொடங்கி முடிக்கின்றனர். ஒவ்வொரு ஓட்டுநர் இடைவெளியும் கடுமையான பிரேக் எச்சரிக்கையும் பாதுகாப்பு மதிப்பெண்ணும் சரிபார்க்கப்பட்ட அமர்விற்குச் சொந்தமானவை.",
  pub_ch2_h1: "HMAC-சரிபார்க்கப்பட்ட NFC பணித் தொடக்கம் மற்றும் முடிவுப் பதிவேடு",
  pub_ch2_h2: "கடுமையான பிரேக், விரைவு முடுக்கம், வளைவு & அதிவேக வகைப்பாடு",
  pub_ch2_h3: "அதே நிறுவன வரம்பிற்குள் கட்டமைக்கப்பட்ட ஓட்டுநர் மேல்முறையீட்டு மதிப்பாய்வு",
  pub_ch3_pill: "03 4G/LTE இணைப்பு",
  pub_ch3_eyebrow: "அத்தியாயம் 03 · செல்லுலார் & மேகம்",
  pub_ch3_title: "ஒவ்வொரு வழித்தடத்திலும் பிணைய நுண்ணறிவு.",
  pub_ch3_desc:
    "சாதனம் வாரியான RabbitMQ தனிமைப்படுத்தலுடன் மறைகுறியாக்கப்பட்ட WSS மற்றும் AMQPS வழிகளில் டெலிமெட்ரி பாய்ந்து, செல்லுலார் சேவையாளர், RSRP மற்றும் SINR தரத்தைப் பதிவு செய்கிறது.",
  pub_ch3_h1: "சாதனம் வாரியான தரகர் சான்றுகள் & கடுமையான vhost/topic ACL எல்லைகள்",
  pub_ch3_h2: "நேரடி & வரலாற்று 4G/LTE RSRP மற்றும் SINR வழித்தட வரைபடம்",
  pub_ch3_h3:
    "சிக்னல் இல்லாத பகுதிகளைச் செயலிழப்பாகக் குழப்பாமல் ஏற்றுமதி செய்யக்கூடிய CSV பதிவுகள்",
  pub_ch4_pill: "04 இணக்கம் & AI",
  pub_ch4_eyebrow: "அத்தியாயம் 04 · செயல்பாடுகள் & இணக்கம்",
  pub_ch4_title: "செயல்பாடுகள் மற்றும் ஒழுங்குமுறைத் தயார்நிலைக்கான ஒரே பதிவு.",
  pub_ch4_desc:
    "இயக்குநர்கள் இணக்கக் காலக்கெடுக்கள், மைலேஜ் பராமரிப்புத் தூண்டிகள், குழு ஆற்றல் மதிப்பீடுகள் மற்றும் விருப்பமான தற்காலிக Google AI கோளாறு ஆலோசனைகளை ஒரே பணியிடத்தில் ஆய்வு செய்கின்றனர்.",
  pub_ch4_h1: "PUSPAKOM ஆய்வுகள், சாலை வரி (LKM) & வணிக வாகனக் காப்பீட்டு எச்சரிக்கைகள்",
  pub_ch4_h2: "உண்மையான ஓடோமீட்டர் முன்னேற்றத்துடன் இணைக்கப்பட்ட மைலேஜ் பராமரிப்பு வரம்புகள்",
